[CmdletBinding(SupportsShouldProcess)]param([Parameter(Mandatory)][ValidateSet('Windows 10','Windows 11','Office','Teams','Edge','Intune')][string]$Category,[Parameter(Mandatory)][string]$Product,[Parameter(Mandatory)][string]$Version,[Parameter(Mandatory)][ValidatePattern('^KB\d+$')][string]$KB,[Parameter(Mandatory)][datetime]$ReleaseDate,[string]$OSBuild,[Parameter(Mandatory)][ValidatePattern('^https://(support|learn)\.microsoft\.com/')][uri]$DocumentationUrl,[string]$Path=(Join-Path $PSScriptRoot '../data/updates.json'))
$ErrorActionPreference='Stop';$resolved=[IO.Path]::GetFullPath($Path);$data=Get-Content -Raw -LiteralPath $resolved|ConvertFrom-Json;if($data.updates.kb -contains $KB){throw "KB bereits vorhanden: $KB"};$item=[pscustomobject]@{category=$Category;product=$Product;version=$Version;kb=$KB.ToUpperInvariant();releaseDate=$ReleaseDate.ToString('yyyy-MM-dd');osBuild=$OSBuild;documentationUrl=$DocumentationUrl.AbsoluteUri};if($PSCmdlet.ShouldProcess($resolved,"$KB hinzufügen")){$data.updates=@($data.updates)+$item|Sort-Object releaseDate -Descending;$data.lastUpdated=(Get-Date).ToString('yyyy-MM-dd');$data|ConvertTo-Json -Depth 8|Set-Content -LiteralPath $resolved -Encoding utf8}